using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            using var transaction = db.Database.BeginTransaction();
            db.Database.Migrate();
            transaction.Commit();
        });
    }

    // BREAKING CHANGE 2: EF Core 9 Cosmos provider no longer supports synchronous
    // I/O. Calls like .ToList(), .First(), .Single() etc. now throw
    // InvalidOperationException. You must use async equivalents.
    async Task QueryCosmosAsync(CosmosDbContext cosmos)
    {
        // BEFORE (EF Core 8 - sync, now throws in EF Core 9):
        //   var products = cosmos.Products.Where(p => p.Category == "Electronics").ToList();
        //   var first = cosmos.Products.First(p => p.Id == "abc");

        // AFTER (EF Core 9 - async required for Cosmos provider):
        var products = await cosmos.Products
            .Where(p => p.Category == "Electronics")
            .ToListAsync();

        var first = await cosmos.Products
            .FirstAsync(p => p.Id == "abc");
    }
}

